describe('ML-KEM-keyGen-FIPS203 (NIST CAVP, 9 sub-samples / 75 total)', () => {
    test.each(_KG)(
        'tgId=$tg tcId=$tc ($ps): keygen(d||z) == (ek, dk)',
        (v) => {
            const seed = new Uint8Array(64);
            seed.set(_hex.toBytes(v.d), 0);
            seed.set(_hex.toBytes(v.z), 32);
            const kp = _MLKEM[v.ps].keygen(seed);
            expect(kp).not.toBe(false);
            expect(_hex.fromBytes(kp.publicKey)).toBe(v.ek.toLowerCase());
            expect(_hex.fromBytes(kp.secretKey)).toBe(v.dk.toLowerCase());
        },
        30_000
    );
});

describe('ML-KEM-encapDecap-FIPS203 / encapsulation (NIST CAVP, 9 sub-samples / 75 total)', () => {
    test.each(_ENC)(
        'tgId=$tg tcId=$tc ($ps): encapsulate(ek, m) == (c, k)',
        (v) => {
            const ek = _hex.toBytes(v.ek);
            const m  = _hex.toBytes(v.m);
            const r  = _MLKEM[v.ps].encapsulate(ek, m);
            expect(r).not.toBe(false);
            expect(_hex.fromBytes(r.cipherText)).toBe(v.c.toLowerCase());
            expect(_hex.fromBytes(r.sharedSecret)).toBe(v.k.toLowerCase());
        },
        30_000
    );
});

describe('ML-KEM-encapDecap-FIPS203 / decapsulation (NIST CAVP, 9 sub-samples / 30 total)', () => {
    test.each(_DEC)(
        'tgId=$tg tcId=$tc ($ps): decapsulate(c, dk) == k',
        (v) => {
            const dk = _hex.toBytes(v.dk);
            const c  = _hex.toBytes(v.c);
            const k  = _MLKEM[v.ps].decapsulate(c, dk);
            expect(_hex.fromBytes(k)).toBe(v.k.toLowerCase());
        },
        30_000
    );
});

describe('ML-KEM-encapDecap-FIPS203 / decapsulationKeyCheck (NIST CAVP, 30/30 vectors)', () => {
    test.each(_DKC)(
        'tgId=$tg tcId=$tc ($ps, expected=$pass): _internal.isValidDecapsulationKey(dk)',
        (v) => {
            const ok = _MLKEM[v.ps]._internal.isValidDecapsulationKey(_hex.toBytes(v.dk));
            expect(ok).toBe(v.pass);
        }
    );
});

describe('ML-KEM-encapDecap-FIPS203 / encapsulationKeyCheck (NIST CAVP, 30/30 vectors)', () => {
    test.each(_EKC)(
        'tgId=$tg tcId=$tc ($ps, expected=$pass): _internal.isValidEncapsulationKey(ek)',
        (v) => {
            const ok = _MLKEM[v.ps]._internal.isValidEncapsulationKey(_hex.toBytes(v.ek));
            expect(ok).toBe(v.pass);
        }
    );
});

// ── Iteration H3 - Full ACVP coverage gated behind CRYPTO_FULL ───────────────
//
// The `CRYPTO_FULL=1` flag unlocks all ACVP NIST CAVP vectors
// (75 keyGen + 165 encapDecap = 240 cases for ML-KEM). Without the flag, the
// default suite keeps the 9 sub-samples [first/mid/last] per paramSet to
// stay < 1 s in CI. Vectors are loaded via synchronous `readFileSync`:
// the I/O cost stays ~10 ms and is only paid when the flag is set.
const RUN_FULL_H3 = process.env.CRYPTO_FULL === '1';
if (RUN_FULL_H3) {
    const { readFileSync } = await import('node:fs');
    const _ROOT = new URL('../../../tests/_vectors/', import.meta.url);
    const _load = (name) => {
        const p = JSON.parse(readFileSync(new URL(`${name}/internalProjection.json`, _ROOT), 'utf8'));
        const e = JSON.parse(readFileSync(new URL(`${name}/expectedResults.json`, _ROOT), 'utf8'));
        const expByTc = new Map();
        for (const g of e.testGroups) for (const t of g.tests) expByTc.set(t.tcId, t);
        const out = [];
        for (const g of p.testGroups) {
            for (const t of g.tests) {
                const exp = expByTc.get(t.tcId);
                out.push({ tg: g.tgId, tc: t.tcId, ps: g.parameterSet, function: g.function || g.testType, ...t, ...exp });
            }
        }
        return out;
    };

    describe('ML-KEM-keyGen-FIPS203 - full ACVP (CRYPTO_FULL, 75/75)', () => {
        const ALL = _load('ML-KEM-keyGen-FIPS203');
        test.each(ALL)('tgId=$tg tcId=$tc ($ps)', (v) => {
            const seed = new Uint8Array(64);
            seed.set(_hex.toBytes(v.d), 0);
            seed.set(_hex.toBytes(v.z), 32);
            const kp = _MLKEM[v.ps].keygen(seed);
            expect(_hex.fromBytes(kp.publicKey)).toBe(v.ek.toLowerCase());
            expect(_hex.fromBytes(kp.secretKey)).toBe(v.dk.toLowerCase());
        }, 30_000);
    });

    describe('ML-KEM-encapDecap-FIPS203 - full ACVP (CRYPTO_FULL, 165/165)', () => {
        const ALL = _load('ML-KEM-encapDecap-FIPS203');
        for (const v of ALL) {
            const fn = v.function;
            if (fn === 'encapsulation') {
                test(`tgId=${v.tg} tcId=${v.tc} (${v.ps}) encapsulate`, () => {
                    const r = _MLKEM[v.ps].encapsulate(_hex.toBytes(v.ek), _hex.toBytes(v.m));
                    expect(_hex.fromBytes(r.cipherText)).toBe(v.c.toLowerCase());
                    expect(_hex.fromBytes(r.sharedSecret)).toBe(v.k.toLowerCase());
                }, 30_000);
            } else if (fn === 'decapsulation') {
                test(`tgId=${v.tg} tcId=${v.tc} (${v.ps}) decapsulate`, () => {
                    const k = _MLKEM[v.ps].decapsulate(_hex.toBytes(v.c), _hex.toBytes(v.dk));
                    expect(_hex.fromBytes(k)).toBe(v.k.toLowerCase());
                }, 30_000);
            } else if (fn === 'decapsulationKeyCheck') {
                test(`tgId=${v.tg} tcId=${v.tc} (${v.ps}) decapKeyCheck → ${v.testPassed}`, () => {
                    expect(_MLKEM[v.ps]._internal.isValidDecapsulationKey(_hex.toBytes(v.dk))).toBe(v.testPassed);
                });
            } else if (fn === 'encapsulationKeyCheck') {
                test(`tgId=${v.tg} tcId=${v.tc} (${v.ps}) encapKeyCheck → ${v.testPassed}`, () => {
                    expect(_MLKEM[v.ps]._internal.isValidEncapsulationKey(_hex.toBytes(v.ek))).toBe(v.testPassed);
                });
            }
        }
    });
}
